tape( 'the function is an odd function of x', function test( t ) {
	var yn;
	var yp;
	var x;
	var z;
	var i;

	for ( i = 0; i < 500; i++ ) {
		x = float64ToFloat32( randu() * 36.0 );
		z = [ 0.0, 0.0 ];
		yn = fresnelf( -x, z, 1, 0 );
		t.strictEqual( yn, z, 'returns expected value' );

		z = [ 0.0, 0.0 ];
		yp = fresnelf( x, z, 1, 0 );
		t.strictEqual( yp, z, 'returns expected value' );

		t.strictEqual( yp[0], -yn[0], 'S(x) = -S(-x)' );
		t.strictEqual( yp[1], -yn[1], 'C(x) = -C(-x)' );
	}
	t.end();
});

tape( 'the function returns `[0.5, 0.5]` if provided `+infinity`', function test( t ) {
	var v;
	var z;

	z = [ 0.0, 0.0 ];
	v = fresnelf( PINF, z, 1, 0 );
	t.strictEqual( v, z, 'returns expected value' );
	t.strictEqual( v[0], 0.5, 'returns 0.5' );
	t.strictEqual( v[1], 0.5, 'returns 0.5' );
	t.end();
});

tape( 'the function returns `[-0.5, -0.5]` if provided `-infinity`', function test( t ) {
	var v;
	var z;

	z = [ 0.0, 0.0 ];
	v = fresnelf( NINF, z, 1, 0 );
	t.strictEqual( v, z, 'returns expected value' );
	t.strictEqual( v[0], -0.5, 'returns -0.5' );
	t.strictEqual( v[1], -0.5, 'returns -0.5' );
	t.end();
});

tape( 'the function returns `[NaN, NaN]` if provided a `NaN`', function test( t ) {
	var v;
	var z;

	z = [ 0.0, 0.0 ];
	v = fresnelf( NaN, z, 1, 0 );
	t.strictEqual( v, z, 'returns expected value' );
	t.strictEqual( isnanf( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnanf( v[1] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a stride', function test( t ) {
	var out;
	var val;

	out = new Float32Array( 4 );
	val = fresnelf( NINF, out, 2, 0 );

	t.strictEqual( val, out, 'returns output array' );
	t.strictEqual( val[0], -0.5, 'returns expected value' );
	t.strictEqual( val[1], 0, 'returns expected value' );
	t.strictEqual( val[2], -0.5, 'returns expected value' );
	t.strictEqual( val[3], 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying an offset', function test( t ) {
	var out;
	var val;

	out = new Float32Array( 4 );
	val = fresnelf( NINF, out, 2, 1 );

	t.strictEqual( val, out, 'returns output array' );
	t.strictEqual( val[0], 0, 'returns expected value' );
	t.strictEqual( val[1], -0.5, 'returns expected value' );
	t.strictEqual( val[2], 0, 'returns expected value' );
	t.strictEqual( val[3], -0.5, 'returns expected value' );

	t.end();
});
